  if(reached)head+='<div class="calc-next-action"><strong>Ta prochaine étape</strong><p>'+esc(g.kind==='purchase'?'Achète '+goalShort(s)+' quand tu veux : il te restera '+money(r.finalCash-(r.input.goalPrice||0))+'. Ensuite, choisis un nouveau but.':'Ton but est atteint. Choisis-en un plus grand, ou un achat.')+'</p></div>';
  else if(next)head+='<div class="calc-next-action"><strong>Ta prochaine partie ('+D+')</strong>'+(next.steps.length?'<ol class="b-next-steps">'+next.steps.map(st=>'<li>« '+esc(st.name)+' » ×'+st.runs+' <span>+'+money(st.net)+'</span></li>').join('')+'</ol>':'<p>Joue '+D+' : +'+money(next.gain)+' environ.</p>')+'<p>'+esc('Tu passes de '+money(r.startCash)+' à '+money(next.cashAfter+next.purchases.reduce((a,n)=>{const x=r.purchases.find(y=>y.name===n);return a+(x?x.price:0);},0))+'.')+(next.purchases.length?' <b>Puis achète : '+esc(next.purchases.join(', '))+'</b> → il te reste '+money(next.cashAfter)+'.':'')+(g.kind==='unlock'&&next.unitsGain>0?' +'+units(s,next.unitsGain)+'.':'')+'</p>'+btn('Après avoir joué, écrire ce que j’ai vraiment','data-b-focus="plan-actual"')+'</div>';
  if(mode!=='advanced')head+='<label class="calc-check"><input type="checkbox" data-b-plan-details="1" '+(p.details?'checked':'')+'> Afficher plus de détails (partie par partie, et si, courbe, calendrier)</label>';
  $('plan-results').innerHTML=head;markSkips(s);
  /* ---- Le document : des « gros points » repliables. La réponse est au-dessus ; ici, chaque point s'ouvre d'un geste. ---- */
  const obs=B.planObserved(s),deadline=B.planDeadline(s,r),curve=B.planCurve(r);
  let doc='<div class="calc-card calc-subsection b-doc"><div class="b-doc-head"><div><p class="calc-kicker">MON BUSINESS PLAN · '+esc(new Date().toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'}))+'</p><h3>'+esc(goalName(s).charAt(0).toUpperCase()+goalName(s).slice(1))+'</h3><p class="b-doc-meta">'+esc(reached?'Déjà possible avec ce que tu as.':plural(r.totalSessions,'partie')+' de '+D+' · '+plural(r.days,'jour')+' · '+(p.source==='missions'?plural(p.missions.length,'mission')+' au choix':money(si.hourly)+' par heure')+(r.purchases.some(x=>!x.owned||x.atSession)?' · '+plural(r.purchases.filter(x=>x.atSession).length,'achat')+' d’avant':'')+' · tes chiffres, pas ceux du jeu')+'</p></div><div class="b-doc-tools">'+btn('Tout déplier','data-b-fold-all="open"')+btn('Tout replier','data-b-fold-all="close"')+'</div></div><p class="b-doc-hint">Appuie sur un point pour l’ouvrir. Les chiffres importants sont déjà dans chaque titre.</p>';
  let n=0;const section=(id,title,teaser,lead,body,tone)=>fold('plan-'+id,{n:++n,title,teaser,tone,body:()=>(lead?'<p class="b-doc-lead">'+lead+'</p>':'')+(typeof body==='function'?body():body)});
  /* 1. Programme */
  doc+=section('program','Ton programme, dans l’ordre',reached?'Déjà possible : rien à faire avant ton but':(first&&first.steps.length?'En premier : '+stepsText(first.steps)+' · <b>'+plural(r.totalSessions,'partie')+'</b>, '+plural(r.phases.length,'étape'):'<b>'+plural(r.totalSessions,'partie')+'</b> de '+D+' · '+plural(r.days,'jour')),reached?'':'Ce qu’il faut faire en premier, en deuxième, en troisième… C’est le chemin le plus rapide trouvé avec tes missions et ton temps.',()=>phaseCards(s,r)+(reached?'':'<p class="calc-note">Comment l’ordre est choisi : à chaque partie, on prend les missions qui rapportent le plus dans le temps de la partie, avec l’argent que tu as à ce moment-là. Un achat d’avant se fait dès que tu peux le payer sans toucher à ta réserve ; s’il débloque une mission ou rapporte de l’argent, la suite va plus vite.'+(r.limited?' Le programme vient des enchaînements comparés à chaque partie : il peut en exister un plus rapide.':'')+'</p>'),'main');
