  doc+=section('start','Ton point de départ',esc(money(si.capital)+' en poche · '+D+' · '+dpw+' j/sem · '+(p.source==='missions'?plural(p.missions.length,'mission'):money(si.hourly)+'/h')),'Les chiffres qui font ce plan. Change-en un : tout se recalcule.','<ul class="b-assumptions">'+start.map(([l,v,f])=>'<li><span>'+esc(l)+'</span><b>'+v+'</b>'+btn('Modifier','data-b-focus="'+f+'"')+'</li>').join('')+'</ul><p class="calc-note">Rien ne vient du vrai jeu : prix, gains et temps sont tes chiffres, ou ceux que le site indique comme repères.</p>');
